// GENERATED by backend-crm `npm run sync:pdf-document` from src/modules/pdf/document. Do not edit here.
import type { Band, Block, BlockOf, Box, Column, PdfDocument, RichMark, RichText, Section, Style, Theme } from './schema';

/**
 * PdfDocument + record context → HTML. The server feeds the result to Chromium; the builder canvas renders each
 * block with the same functions (mode `editor`), so what admins see is what prints.
 *
 * Every value is HTML-escaped and every style comes from validated numbers / enums / colours, so the output
 * needs no sanitizing. Styles are inline (Chromium's header / footer templates get no page CSS).
 */

/** The record context (PdfContext on the server): values are looked up by dotted path. */
export type RenderContext = Record<string, unknown>;

export interface RenderOptions {
    /** `pdf`: empty / hidden things are dropped. `editor`: they render as faded placeholders. */
    mode: 'pdf' | 'editor';
    /** `src` for an uploaded image (data: URI on the server, API URL in the browser); null when unknown. */
    assetSrc: (key: string) => string | null;
    /** Label of a field path, for editor placeholders. */
    fieldLabel?: (path: string) => string;
}

// ─── Helpers ────────────────────────────────────────────────────────────────────

export const escapeHtml = (value: string): string =>
    value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const multiline = (value: string): string => escapeHtml(value).replace(/\r?\n/g, '<br>');
const num = (value: number): string => String(Math.round(value * 100) / 100);
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);

export const MUTED = '#64748b';
export const BORDER = '#cbd5e1';

export function resolveColor(color: string | null | undefined, theme: Theme): string | undefined {
    if (!color) return undefined;
    if (color === 'accent') return theme.accentColor;
    return color;
}

/** Text (never markup) at a dotted path; '' when missing. Numbers and booleans are stringified. */
export function getValue(ctx: RenderContext, path: string): string {
    let current: unknown = ctx;
    for (const part of path.split('.')) {
        if (!isRecord(current) || !Object.prototype.hasOwnProperty.call(current, part)) return '';
        current = current[part];
    }
    if (current === null || current === undefined) return '';
    if (typeof current === 'string') return current;
    if (typeof current === 'number' || typeof current === 'boolean') return String(current);
    return '';
}

const boxCss = (prop: 'padding' | 'margin', box: Box | undefined): string =>
    box ? `${prop}:${num(box.top)}mm ${num(box.right)}mm ${num(box.bottom)}mm ${num(box.left)}mm;` : '';

/** Inline CSS declarations for a style object. */
export function styleToCss(style: Style | undefined, theme: Theme): string {
    if (!style) return '';
    let css = boxCss('padding', style.padding) + boxCss('margin', style.margin);
    const bg = resolveColor(style.background, theme);
    if (bg) css += `background:${bg};`;
    if (style.border && style.border.width > 0) {
        const b = style.border;
        const line = `${num(b.width)}px ${b.style} ${resolveColor(b.color, theme)}`;
        const { top, right, bottom, left } = b.sides;
        if (top && right && bottom && left) css += `border:${line};`;
        else {
            if (top) css += `border-top:${line};`;
            if (right) css += `border-right:${line};`;
            if (bottom) css += `border-bottom:${line};`;
            if (left) css += `border-left:${line};`;
        }
    }
    if (style.border && style.border.radius > 0) css += `border-radius:${num(style.border.radius)}px;`;
    if (style.textAlign) css += `text-align:${style.textAlign};`;
    if (style.verticalAlign) css += `vertical-align:${style.verticalAlign};`;
    if (style.fontSize) css += `font-size:${num(style.fontSize)}pt;`;
    if (style.fontWeight) css += `font-weight:${style.fontWeight === 'bold' ? 700 : 400};`;
    if (style.fontStyle) css += `font-style:${style.fontStyle};`;
    const color = resolveColor(style.color, theme);
    if (color) css += `color:${color};`;
    if (style.lineHeight) css += `line-height:${num(style.lineHeight)};`;
    if (style.letterSpacing) css += `letter-spacing:${num(style.letterSpacing)}px;`;
    if (style.textTransform) css += `text-transform:${style.textTransform};`;
    if (style.width && style.width < 100) {
        css += `width:${num(style.width)}%;`;
        // Position the narrowed box in its column (auto margins override the left / right spacing on that side).
        if (style.blockAlign === 'center') css += 'margin-left:auto;margin-right:auto;';
        else if (style.blockAlign === 'right') css += 'margin-left:auto;';
    }
    if (style.minHeight) css += `min-height:${num(style.minHeight)}mm;`;
    if (style.avoidPageBreak) css += 'break-inside:avoid;page-break-inside:avoid;';
    return css;
}

/** Base typography of a band (body / header / footer). */
export function bandBaseCss(theme: Theme): string {
    return `font-size:${num(theme.fontSize)}pt;line-height:${num(theme.lineHeight)};color:${theme.textColor};`;
}

export function sectionCss(section: Section, theme: Theme): string {
    return styleToCss(section.style, theme);
}

export function columnCss(column: Column, theme: Theme): string {
    return `width:${num(column.widthPct)}%;vertical-align:${column.style.verticalAlign ?? 'top'};${styleToCss({ ...column.style, verticalAlign: undefined }, theme)}`;
}

export function blockCss(block: Block, theme: Theme): string {
    return styleToCss(block.style, theme);
}

const placeholder = (text: string): string =>
    `<span style="color:#94a3b8;font-style:italic;background:#f1f5f9;border-radius:3px;padding:0 3px">${escapeHtml(text)}</span>`;

// ─── Rich text ──────────────────────────────────────────────────────────────────

function applyMarks(html: string, marks: RichMark[] | undefined, theme: Theme): string {
    if (!marks) return html;
    let out = html;
    for (const mark of marks) {
        if (mark.type === 'bold') out = `<strong>${out}</strong>`;
        else if (mark.type === 'italic') out = `<em>${out}</em>`;
        else if (mark.type === 'underline') out = `<u>${out}</u>`;
        else if (mark.type === 'textStyle') {
            const color = resolveColor(mark.attrs.color ?? undefined, theme);
            if (color) out = `<span style="color:${color}">${out}</span>`;
        }
    }
    return out;
}

/** Whether rich text contains any visible text or a non-empty field. */
export function richTextHasContent(content: RichText, ctx: RenderContext): boolean {
    return content.content.some((p) => p.content?.some((n) => (n.type === 'text' && n.text.trim() !== '') || (n.type === 'field' && getValue(ctx, n.attrs.path) !== '')));
}

export function renderRichText(content: RichText, ctx: RenderContext, theme: Theme, opts: RenderOptions): string {
    return content.content
        .map((p) => {
            const align = p.attrs?.textAlign ? `text-align:${p.attrs.textAlign};` : '';
            const inner = (p.content ?? [])
                .map((n) => {
                    if (n.type === 'hardBreak') return '<br>';
                    if (n.type === 'text') return applyMarks(escapeHtml(n.text), n.marks, theme);
                    const value = getValue(ctx, n.attrs.path);
                    if (value) return applyMarks(multiline(value), n.marks, theme);
                    return opts.mode === 'editor' ? placeholder(opts.fieldLabel?.(n.attrs.path) ?? n.attrs.path) : '';
                })
                .join('');
            return `<p style="margin:0;${align}">${inner || '<br>'}</p>`;
        })
        .join('');
}

// ─── Blocks ─────────────────────────────────────────────────────────────────────

export interface BlockRender {
    html: string;
    /** True when the block has nothing to show for this record (hidden in the PDF when `hideIfEmpty`). */
    empty: boolean;
}

const TITLE_SIZES: Record<1 | 2 | 3, number> = { 1: 20, 2: 15, 3: 12 };

function labelCss(color: string | undefined, bold: boolean, theme: Theme): string {
    return `color:${resolveColor(color, theme) ?? MUTED};font-weight:${bold ? 700 : 600};`;
}

function imageHtml(src: string | null, widthMm: number, heightMm: number, alt: string, opts: RenderOptions, emptyLabel: string): BlockRender {
    if (!src) return { html: opts.mode === 'editor' ? `<div style="border:1px dashed ${BORDER};color:#94a3b8;padding:6mm;text-align:center;font-size:9pt">${escapeHtml(emptyLabel)}</div>` : '', empty: true };
    const size = `${widthMm ? `width:${num(widthMm)}mm;` : 'max-width:100%;'}${heightMm ? `height:${num(heightMm)}mm;` : ''}`;
    return { html: `<img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" style="${size}object-fit:contain;display:inline-block;vertical-align:middle">`, empty: false };
}

function lineItemsHtml(block: BlockOf<'lineItems'>, ctx: RenderContext, theme: Theme): BlockRender {
    const p = block.props;
    const visible = p.columns.filter((c) => c.visible);
    const underName = p.descriptionUnderName && visible.some((c) => c.key === 'description') && visible.some((c) => c.key === 'productName');
    const columns = underName ? visible.filter((c) => c.key !== 'description') : visible;
    const items = Array.isArray(ctx.lineItems) ? (ctx.lineItems as Record<string, unknown>[]) : [];
    const border = resolveColor(p.borderColor, theme) ?? BORDER;
    const cellBorder = p.borders === 'grid' ? `border:1px solid ${border};` : p.borders === 'rows' ? `border-bottom:1px solid ${border};` : '';
    const font = p.fontSize ? `font-size:${num(p.fontSize)}pt;` : '';
    const headBg = resolveColor(p.headerBackground, theme);
    const headColor = resolveColor(p.headerColor, theme);
    const th = columns
        .map(
            (c) =>
                `<th data-col="${escapeHtml(c.key)}" style="text-align:${c.align};${c.widthPct ? `width:${num(c.widthPct)}%;` : ''}padding:1.5mm;font-weight:700;white-space:nowrap;${headBg ? `background:${headBg};` : ''}${headColor ? `color:${headColor};` : ''}${p.borders === 'grid' ? `border:1px solid ${headBg && headBg !== 'transparent' ? headBg : border};` : `border-bottom:1.5px solid ${border};`}">${escapeHtml(c.label)}</th>`,
        )
        .join('');
    const cell = (item: Record<string, unknown>, key: string): string => {
        const formatted = item[`${key}Formatted`];
        const raw = formatted !== undefined ? formatted : item[key];
        const text = raw === null || raw === undefined ? '' : String(raw);
        return key === 'description' || key === 'note' ? multiline(text) : escapeHtml(text.replace(/\r?\n/g, ' '));
    };
    const rows = items.length
        ? items
              .map((item, index) => {
                  const zebra = p.zebra && index % 2 === 1 ? 'background:#f8fafc;' : '';
                  return `<tr>${columns
                      .map((c) => {
                          let inner = cell(item, c.key);
                          if (underName && c.key === 'productName' && item.description) {
                              inner += `<div style="color:${MUTED};font-size:0.9em;margin-top:0.5mm">${multiline(String(item.description))}</div>`;
                          }
                          return `<td style="text-align:${c.align};padding:1.5mm;vertical-align:top;${cellBorder}${zebra}${c.align === 'right' ? 'white-space:nowrap;' : ''}">${inner}</td>`;
                      })
                      .join('')}</tr>`;
              })
              .join('')
        : `<tr><td colspan="${columns.length || 1}" style="text-align:center;padding:2mm;color:${MUTED};${cellBorder}">${escapeHtml(p.emptyText)}</td></tr>`;
    return {
        html: `<table style="width:100%;border-collapse:collapse;${font}"><thead><tr>${th}</tr></thead><tbody>${rows}</tbody></table>`,
        empty: items.length === 0,
    };
}

function totalsHtml(block: BlockOf<'totals'>, ctx: RenderContext, theme: Theme, opts: RenderOptions): BlockRender {
    const p = block.props;
    const totals = isRecord(ctx.totals) ? ctx.totals : {};
    const border = p.bordered ? `border:1px solid ${BORDER};` : '';
    const grandBg = resolveColor(p.grandTotalBackground ?? 'accent', theme) ?? theme.accentColor;
    const grandColor = resolveColor(p.grandTotalColor ?? '#ffffff', theme) ?? '#ffffff';
    const rows = p.rows
        .filter((row) => row.visible)
        .filter((row) => opts.mode === 'editor' || !row.hideIfZero || Number(totals[row.key] ?? 0) !== 0)
        .map((row) => {
            const value = getValue(ctx, `totals.${row.key}Formatted`);
            const minus = (row.key === 'totalDiscount' || row.key === 'lumpSumDiscount') && value ? '- ' : '';
            const grand = row.key === 'grandTotal' && p.highlightGrandTotal ? `background:${grandBg};color:${grandColor};font-weight:700;` : '';
            return `<tr><th data-total="${row.key}" style="text-align:left;font-weight:${row.key === 'grandTotal' ? 700 : 600};padding:1mm 2mm;width:${num(p.labelWidthPct)}%;${border}${grand}">${escapeHtml(row.label)}</th><td style="text-align:right;padding:1mm 2mm;white-space:nowrap;${border}${grand}">${minus}${escapeHtml(value)}</td></tr>`;
        })
        .join('');
    return { html: `<table style="width:100%;border-collapse:collapse">${rows}</table>`, empty: rows === '' };
}

function termsHtml(block: BlockOf<'terms'>, ctx: RenderContext, theme: Theme, opts: RenderOptions): BlockRender {
    const p = block.props;
    const titleCss = `font-weight:700;color:${resolveColor(p.titleColor, theme) ?? theme.accentColor};border-bottom:1px solid ${BORDER};padding-bottom:0.5mm;margin-bottom:1mm;break-after:avoid;page-break-after:avoid;`;
    const parts = p.sections
        .filter((s) => s.visible)
        .map((s) => {
            let body = '';
            if (s.key === 'paymentTerms') {
                const head = getValue(ctx, 'terms.paymentTerms');
                const detail = getValue(ctx, 'terms.paymentTermsDescription');
                body = (head ? `<div style="font-weight:700">${escapeHtml(head)}</div>` : '') + (detail ? `<div>${multiline(detail)}</div>` : '');
            } else if (s.key === 'termsAndConditions') {
                const detail = getValue(ctx, 'terms.termsAndConditionDescription');
                body = detail ? `<div>${multiline(detail)}</div>` : '';
            } else {
                const remarks = getValue(ctx, 'record.remarks');
                body = remarks ? `<div>${multiline(remarks)}</div>` : '';
            }
            if (!body && opts.mode === 'pdf') return '';
            const content = body || placeholder(`${s.title} (empty for this record)`);
            return `<div style="margin-bottom:3mm;break-inside:avoid;page-break-inside:avoid">${p.showTitles && s.title ? `<div style="${titleCss}">${escapeHtml(s.title)}</div>` : ''}${content}</div>`;
        })
        .join('');
    return { html: parts, empty: parts === '' };
}

function kvTable(rows: { label: string; value: string }[], labelWidthPct: number, labelStyle: string, valueStyle: string, bordered: boolean): string {
    const border = bordered ? `border:1px solid ${BORDER};padding:1mm 2mm;` : 'padding:0.5mm 2mm 0.5mm 0;';
    return `<table style="width:100%;border-collapse:collapse">${rows
        .map(
            (r) =>
                `<tr><th style="text-align:left;vertical-align:top;width:${num(labelWidthPct)}%;${border}${labelStyle}">${escapeHtml(r.label)}</th><td style="vertical-align:top;${border}${valueStyle}">${r.value}</td></tr>`,
        )
        .join('')}</table>`;
}

/** The block's content (without its own wrapper / style). */
export function renderBlockContent(block: Block, ctx: RenderContext, theme: Theme, opts: RenderOptions): BlockRender {
    const editor = opts.mode === 'editor';
    switch (block.type) {
        case 'title': {
            const size = block.style.fontSize ? '' : `font-size:${TITLE_SIZES[block.props.level]}pt;`;
            const weight = block.style.fontWeight ? '' : 'font-weight:700;';
            return {
                html: `<div style="${size}${weight}line-height:1.2">${renderRichText(block.props.content, ctx, theme, opts)}</div>`,
                empty: !richTextHasContent(block.props.content, ctx),
            };
        }
        case 'text':
            return { html: renderRichText(block.props.content, ctx, theme, opts), empty: !richTextHasContent(block.props.content, ctx) };
        case 'image': {
            const key = block.props.source === 'logo' ? theme.logoAssetKey : block.props.assetKey;
            const img = imageHtml(key ? opts.assetSrc(key) : null, block.props.widthMm, block.props.heightMm, block.props.alt, opts, block.props.source === 'logo' ? 'Company logo (upload one in Document settings)' : 'Choose an image');
            return { html: img.html ? `<div style="text-align:${block.props.align}">${img.html}</div>` : '', empty: img.empty };
        }
        case 'divider': {
            const p = block.props;
            const align = block.style.textAlign === 'center' ? 'margin-left:auto;margin-right:auto;' : block.style.textAlign === 'right' ? 'margin-left:auto;' : '';
            return { html: `<div style="border-top:${num(p.thickness)}px ${p.lineStyle} ${resolveColor(p.color, theme) ?? BORDER};width:${num(p.widthPct)}%;height:0;${align}"></div>`, empty: false };
        }
        case 'spacer':
            return { html: `<div style="height:${num(block.props.heightMm)}mm"></div>`, empty: false };
        case 'pageBreak':
            return editor
                ? { html: `<div style="border-top:1px dashed #94a3b8;text-align:center;color:#94a3b8;font-size:8pt;line-height:1;padding-top:1mm">Page break</div>`, empty: false }
                : { html: '<div style="break-before:page;page-break-before:always"></div>', empty: false };
        case 'field': {
            const p = block.props;
            const raw = getValue(ctx, p.path);
            const value = raw ? multiline(raw) : editor ? placeholder(opts.fieldLabel?.(p.path) ?? p.path) : '';
            const label = p.showLabel && p.label ? `<span style="${labelCss(p.labelColor, p.labelBold, theme)}">${escapeHtml(p.label)}${p.layout === 'inline' ? ':' : ''}</span>` : '';
            const html = p.layout === 'inline' ? `${label}${label ? ' ' : ''}${value}` : `${label ? `<div>${label}</div>` : ''}<div>${value}</div>`;
            return { html, empty: raw === '' };
        }
        case 'detailsList': {
            const p = block.props;
            const rows = p.rows
                .map((row) => ({ row, raw: getValue(ctx, row.path) }))
                .filter(({ row, raw }) => editor || raw !== '' || !row.hideIfEmpty)
                .map(({ row, raw }) => ({ label: row.label, value: raw ? multiline(raw) : editor ? placeholder('empty') : '' }));
            return {
                html: rows.length ? kvTable(rows, p.labelWidthPct, labelCss(p.labelColor, false, theme), p.valueBold ? 'font-weight:700;' : '', p.bordered) : '',
                empty: rows.length === 0,
            };
        }
        case 'address': {
            const p = block.props;
            const at = (part: string) => getValue(ctx, `${p.which}.${part}`);
            const cityLine = [p.parts.city ? at('city') : '', p.parts.state ? at('state') : ''].filter(Boolean).join(', ');
            const withPin = [cityLine, p.parts.postalCode ? at('postalCode') : ''].filter(Boolean).join(' - ');
            const lines = [p.parts.street ? at('street') : '', withPin, p.parts.country ? at('country') : ''].filter((l) => l.trim() !== '');
            const title = p.title ? `<div style="font-size:0.85em;text-transform:uppercase;letter-spacing:1px;font-weight:700;color:${theme.accentColor};margin-bottom:0.8mm">${escapeHtml(p.title)}</div>` : '';
            const body = lines.length ? lines.map(multiline).join('<br>') : editor ? placeholder(`${p.which === 'billing' ? 'Billing' : 'Shipping'} address`) : '';
            return { html: `${title}${body}`, empty: lines.length === 0 };
        }
        case 'lineItems':
            return lineItemsHtml(block, ctx, theme);
        case 'totals':
            return totalsHtml(block, ctx, theme, opts);
        case 'amountInWords': {
            const value = getValue(ctx, 'totals.amountInWords');
            const label = block.props.showLabel && block.props.label ? `<div style="color:${MUTED};font-weight:600">${escapeHtml(block.props.label)}</div>` : '';
            return { html: `${label}<div style="font-weight:700">${value ? escapeHtml(value) : editor ? placeholder('Amount in words') : ''}</div>`, empty: value === '' };
        }
        case 'terms':
            return termsHtml(block, ctx, theme, opts);
        case 'customFields': {
            const list = Array.isArray(ctx.customList) ? (ctx.customList as { label?: unknown; value?: unknown }[]) : [];
            const rows = list.filter((r) => typeof r.label === 'string' && typeof r.value === 'string' && r.value !== '').map((r) => ({ label: String(r.label), value: multiline(String(r.value)) }));
            const title = block.props.title ? `<div style="font-weight:700;color:${theme.accentColor};margin-bottom:1mm">${escapeHtml(block.props.title)}</div>` : '';
            if (!rows.length) return { html: editor ? `${title}${placeholder('Custom fields with values appear here')}` : '', empty: true };
            return { html: `${title}${kvTable(rows, block.props.labelWidthPct, `color:${MUTED};font-weight:600;`, '', false)}`, empty: false };
        }
        case 'pageNumber': {
            const parts = block.props.format.split(/(\{page\}|\{total\})/);
            const html = parts
                .map((part) => {
                    if (part === '{page}') return editor ? '1' : '<span class="pageNumber"></span>';
                    if (part === '{total}') return editor ? '2' : '<span class="totalPages"></span>';
                    return escapeHtml(part);
                })
                .join('');
            return { html, empty: false };
        }
        case 'signature': {
            const p = block.props;
            const img = p.assetKey ? opts.assetSrc(p.assetKey) : null;
            const image = img ? `<img src="${escapeHtml(img)}" alt="Signature" style="height:${num(p.heightMm)}mm;max-width:100%;object-fit:contain">` : `<div style="height:${num(p.heightMm)}mm"></div>`;
            const line = p.lineAbove ? `border-top:1px solid ${BORDER};padding-top:1mm;` : '';
            const caption = p.caption ? `<div style="display:inline-block;min-width:45mm;${line}">${escapeHtml(p.caption)}</div>` : '';
            return { html: `<div style="text-align:${p.align}">${image}<div>${caption}</div></div>`, empty: false };
        }
        default: {
            const unknown: never = block;
            return { html: '', empty: Boolean(unknown) };
        }
    }
}

/** A block with its wrapper; '' in the PDF when it is hidden for this record. */
export function renderBlock(block: Block, ctx: RenderContext, theme: Theme, opts: RenderOptions): string {
    const { html, empty } = renderBlockContent(block, ctx, theme, opts);
    if (opts.mode === 'pdf' && (html === '' || (empty && block.hideIfEmpty))) return '';
    return `<div style="${blockCss(block, theme)}">${html}</div>`;
}

export function renderSection(section: Section, ctx: RenderContext, theme: Theme, opts: RenderOptions): string {
    const cells = section.columns
        .map((column) => `<td style="${columnCss(column, theme)}">${column.blocks.map((b) => renderBlock(b, ctx, theme, opts)).join('')}</td>`)
        .join('');
    return `<div style="${sectionCss(section, theme)}"><table style="width:100%;border-collapse:collapse;table-layout:fixed"><tr>${cells}</tr></table></div>`;
}

export function renderBand(doc: PdfDocument, band: Band, ctx: RenderContext, opts: RenderOptions): string {
    const sections = doc[band];
    if (sections.length === 0) return '';
    return `<div style="${bandBaseCss(doc.theme)}">${sections.map((s) => renderSection(s, ctx, doc.theme, opts)).join('')}</div>`;
}

export interface RenderedDocument {
    body: string;
    header: string;
    footer: string;
}

export function renderDocument(doc: PdfDocument, ctx: RenderContext, opts: RenderOptions): RenderedDocument {
    return { body: renderBand(doc, 'body', ctx, opts), header: renderBand(doc, 'header', ctx, opts), footer: renderBand(doc, 'footer', ctx, opts) };
}

/** Every uploaded image the document references (logo included), for prefetching data: URIs. */
export function collectDocumentAssetKeys(doc: PdfDocument): string[] {
    const keys = new Set<string>();
    if (doc.theme.logoAssetKey) keys.add(doc.theme.logoAssetKey);
    for (const band of ['header', 'body', 'footer'] as const) {
        for (const section of doc[band]) {
            for (const column of section.columns) {
                for (const block of column.blocks) {
                    if (block.type === 'image' && block.props.source === 'asset' && block.props.assetKey) keys.add(block.props.assetKey);
                    if (block.type === 'signature' && block.props.assetKey) keys.add(block.props.assetKey);
                }
            }
        }
    }
    return [...keys];
}
